import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.concurrent.atomic.AtomicInteger;

public class TextRed {
    public static void main(String[] args) {
        try {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            int len = Integer.parseInt(reader.readLine());
            String s = reader.readLine();
            reader.close();

            AtomicInteger maxOutside = new AtomicInteger(0);
            AtomicInteger outsideLen = new AtomicInteger(0);
            AtomicInteger insideLen = new AtomicInteger(0);
            AtomicInteger verbCount = new AtomicInteger(0);
            boolean[] inside = {false};

            s.chars().forEachOrdered(ch -> {
                char c = (char) ch;

                if (c == '(') {
                    int out = outsideLen.get();
                    if (out > maxOutside.get()) {
                        maxOutside.set(out);
                    }
                    outsideLen.set(0);
                    inside[0] = true;
                    insideLen.set(0);
                } else if (c == ')') {
                    inside[0] = false;
                    if (insideLen.get() != 0) {
                        verbCount.incrementAndGet();
                    }
                    insideLen.set(0);
                } else if (!inside[0]) {
                    if (c == '_') {
                        int out = outsideLen.get();
                        if (out > maxOutside.get()) {
                            maxOutside.set(out);
                        }
                        outsideLen.set(0);
                    } else {
                        outsideLen.incrementAndGet();
                    }
                } else {
                    if (c == '_') {
                        if (insideLen.get() != 0) {
                            verbCount.incrementAndGet();
                        }
                        insideLen.set(0);
                    } else {
                        insideLen.incrementAndGet();
                    }
                }
            });

            int out = outsideLen.get();
            if (out > maxOutside.get()) {
                maxOutside.set(out);
            }

            System.out.print(maxOutside.get() + " ");
            System.out.print(verbCount.get());
        } catch (Exception e) {
            System.out.println(0 + " 0" + 0);
        }
    }
}
